           1 + import { nextTick } from "vue";
           2 + import { afterEach, describe, expect, test } from "vitest";
           3 + 
           4 + import { containerCardProject, containerCardProjects } from "./containerCardTemplates";
           5 + import { hostspaces, selectedHostspace } from "./hostspaces";
           6 + 
           7 + /**
           8 +  * @vitest-environment jsdom
           9 +  */
          10 + describe("container card project hostspaces", () => {
          11 +   afterEach(() => {
          12 +     localStorage.removeItem("DOZZLE_CURRENT_HOSTSPACE");
          13 +   });
          14 + 
          15 +   test("starts a hostspace without project settings from an empty project", async () => {
          16 +     hostspaces.value = [
          17 +       { id: "default", name: "Default", createdAt: "", updatedAt: "", system: true },
          18 +       { id: "team", name: "Team", createdAt: "", updatedAt: "", system: false },
          19 +     ];
          20 +     selectedHostspace.value = "default";
          21 +     await nextTick();
          22 + 
          23 +     const defaultProject = {
          24 +       name: "Default project",
          25 +       description: "Default description",
          26 +       iconUrl: "https://example.com/icon.svg",
          27 +       fields: [{ id: "docs", label: "Docs", kind: "link" as const, value: "https://example.com" }],
          28 +     };
          29 +     containerCardProjects.value = { default: defaultProject };
          30 +     containerCardProject.value = defaultProject;
          31 + 
          32 +     selectedHostspace.value = "team";
          33 +     await nextTick();
          34 + 
          35 +     expect(containerCardProject.value).toEqual({ name: "", description: "", iconUrl: "", fields: [] });
          36 +     expect(containerCardProjects.value.default).toEqual(defaultProject);
          37 +   });
          38 + });
